import React, { useRef, useEffect, useState } from "react";
import io from "socket.io-client";

const socket = io("http://localhost:5000");

function App() {
  const canvasRef = useRef(null);
  const [drawing, setDrawing] = useState(false);

  useEffect(() => {
    // Listen for drawing data from server and draw on canvas
    socket.on("drawing", onDrawingEvent);

    return () => {
      socket.off("drawing", onDrawingEvent);
    };
  }, []);

  const onDrawingEvent = (data) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    drawLine(ctx, data.x0, data.y0, data.x1, data.y1, data.color, false);
  };

  const drawLine = (ctx, x0, y0, x1, y1, color, emit) => {
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x1, y1);
    ctx.stroke();
    ctx.closePath();

    if (!emit) return;

    socket.emit("drawing", { x0, y0, x1, y1, color });
  };

  const handleMouseDown = (e) => {
    setDrawing(true);
    const { offsetX, offsetY } = e.nativeEvent;
    const canvas = canvasRef.current;
    canvas.lastX = offsetX;
    canvas.lastY = offsetY;
  };

  const handleMouseMove = (e) => {
    if (!drawing) return;
    const { offsetX, offsetY } = e.nativeEvent;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    drawLine(ctx, canvas.lastX, canvas.lastY, offsetX, offsetY, "black", true);

    canvas.lastX = offsetX;
    canvas.lastY = offsetY;
  };

  const handleMouseUp = () => {
    setDrawing(false);
  };

  return (
    <div style={{ textAlign: "center" }}>
      <h1>Real-Time Collaborative Drawing</h1>
      <canvas
        ref={canvasRef}
        width={800}
        height={600}
        style={{ border: "1px solid black" }}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      />
    </div>
  );
}

export default App;
